package tech.bogomolov.incomingsmsgateway;

import java.security.GeneralSecurityException;
import java.security.SecureRandom;

import javax.crypto.Cipher;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;

/**
 * AES-256-GCM with a fresh random IV per encryption. Pure Java, JVM-testable.
 *
 * <p>Wire format: 12-byte IV || ciphertext+tag. The key itself lives in the
 * Android Keystore (see {@link SecureStore}); this class never stores a key.
 *
 * <p>The IV is generated by the cipher provider, never supplied by the
 * caller: Android Keystore keys with randomized encryption required reject
 * caller-provided IVs when encrypting (Android docs: let the Cipher
 * generate the IV and read it with {@code getIV()}). Supplying our own IV
 * is what made encryption fail with "AES-GCM encryption failed" on
 * devices whose Keystore/TEE enforces that rule, even though key
 * generation itself succeeded. Decryption still uses the stored IV, which
 * is allowed.
 */
public final class AesGcm {

    static final int IV_BYTES = 12;
    static final int TAG_BITS = 128;

    private AesGcm() {
    }

    public static byte[] encrypt(SecretKey key, byte[] plaintext) {
        try {
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            cipher.init(Cipher.ENCRYPT_MODE, key);
            byte[] iv = cipher.getIV();
            byte[] ciphertext;
            if (iv != null && iv.length == IV_BYTES) {
                ciphertext = cipher.doFinal(plaintext);
            } else {
                // Provider generated no usable IV: fall back to a
                // caller-generated IV. This works for software keys; a
                // Keystore key with randomized encryption required will
                // reject it, and that failure surfaces as before.
                byte[] fallbackIv = new byte[IV_BYTES];
                new SecureRandom().nextBytes(fallbackIv);
                cipher.init(Cipher.ENCRYPT_MODE, key, new GCMParameterSpec(TAG_BITS, fallbackIv));
                iv = fallbackIv;
                ciphertext = cipher.doFinal(plaintext);
            }
            byte[] out = new byte[IV_BYTES + ciphertext.length];
            System.arraycopy(iv, 0, out, 0, IV_BYTES);
            System.arraycopy(ciphertext, 0, out, IV_BYTES, ciphertext.length);
            return out;
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES-GCM encryption failed", e);
        }
    }

    public static byte[] decrypt(SecretKey key, byte[] combined) {
        try {
            if (combined == null || combined.length <= IV_BYTES) {
                throw new IllegalStateException("ciphertext too short");
            }
            byte[] iv = new byte[IV_BYTES];
            System.arraycopy(combined, 0, iv, 0, IV_BYTES);
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            cipher.init(Cipher.DECRYPT_MODE, key, new GCMParameterSpec(TAG_BITS, iv));
            return cipher.doFinal(combined, IV_BYTES, combined.length - IV_BYTES);
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("AES-GCM decryption failed", e);
        }
    }
}
